fn all_prefixes(s: Vec<char>) -> Vec<Vec<char>> {
    let mut prefixes = Vec::with_capacity(s.len());
    for i in 0..s.len() {
        // Take the slice up to and including index i, and convert to Vec<char>
        prefixes.push(s[0..=i].to_vec());
    }
    prefixes
}

